package chattool

import (
	"context"
	"fmt"
	"strings"

	"charm.land/fantasy"

	"github.com/coder/coder/v2/codersdk"
	"github.com/coder/coder/v2/codersdk/workspacesdk"
)

type EditFilesOptions struct {
	GetWorkspaceConn func(context.Context) (workspacesdk.AgentConn, error)
	ResolvePlanPath  func(context.Context) (chatPath string, home string, err error)
	IsPlanTurn       bool
}

// EditFilesArgs is the tool input schema, auto-generated by the
// fantasy framework from these struct tags.
type EditFilesArgs struct {
	Files []workspacesdk.FileEdits `json:"files" description:"Files to edit. Every entry must include path and at least one edit."`
}

// EditFilesEdit is one edit in the flat edit_files input: a single
// old_text to new_text replacement that carries the path of the file
// it applies to. It is distinct from workspacesdk.FileEdit, which has
// no path and is grouped under workspacesdk.FileEdits for the agent.
type EditFilesEdit struct {
	Path       string `json:"path" description:"Absolute path of the file to edit."`
	OldText    string `json:"old_text" description:"Exact text to replace. Must match exactly one location unless replace_all is true. Must differ from new_text."`
	NewText    string `json:"new_text" description:"Replacement text."`
	ReplaceAll bool   `json:"replace_all,omitempty" description:"Replace every match of old_text."`
}

// GroupEditsByPath groups edits into one entry per path for the
// workspace agent request. Paths compare exactly as given. Files
// appear in order of each path's first edit, and each file keeps its
// edits in their original order, so interleaved paths (a, b, a) group
// to a: [1st, 3rd], b: [2nd]. The result is empty, not nil, for empty
// input.
func GroupEditsByPath(edits []EditFilesEdit) []workspacesdk.FileEdits {
	files := make([]workspacesdk.FileEdits, 0, len(edits))
	indexByPath := make(map[string]int, len(edits))
	for _, edit := range edits {
		i, ok := indexByPath[edit.Path]
		if !ok {
			i = len(files)
			indexByPath[edit.Path] = i
			files = append(files, workspacesdk.FileEdits{Path: edit.Path})
		}
		files[i].Edits = append(files[i].Edits, workspacesdk.FileEdit{
			OldText:    edit.OldText,
			NewText:    edit.NewText,
			ReplaceAll: edit.ReplaceAll,
		})
	}
	return files
}

// EditFilesHookInput is the grouped form of edit_files input that
// pre_tool_use hooks receive as tool_input and return as
// input_override: {"files":[{"path":...,"edits":[...]}]}.
//
// It deliberately does not reuse workspacesdk.FileEdits: the JSON
// methods on workspacesdk.FileEdit emit and accept the deprecated
// search/replace keys for old agents, and hooks must see and send only
// old_text/new_text.
type EditFilesHookInput struct {
	Files []EditFilesHookFile `json:"files"`
}

// EditFilesHookFile holds the edits for one path in
// EditFilesHookInput.
type EditFilesHookFile struct {
	Path  string              `json:"path"`
	Edits []EditFilesHookEdit `json:"edits"`
}

// EditFilesHookEdit is one edit in EditFilesHookFile.
type EditFilesHookEdit struct {
	OldText    string `json:"old_text"`
	NewText    string `json:"new_text"`
	ReplaceAll bool   `json:"replace_all,omitempty"`
}

// NewEditFilesHookInput groups edits by path with the same ordering
// as GroupEditsByPath.
func NewEditFilesHookInput(edits []EditFilesEdit) EditFilesHookInput {
	grouped := GroupEditsByPath(edits)
	input := EditFilesHookInput{Files: make([]EditFilesHookFile, 0, len(grouped))}
	for _, file := range grouped {
		hookFile := EditFilesHookFile{
			Path:  file.Path,
			Edits: make([]EditFilesHookEdit, 0, len(file.Edits)),
		}
		for _, edit := range file.Edits {
			hookFile.Edits = append(hookFile.Edits, EditFilesHookEdit(edit))
		}
		input.Files = append(input.Files, hookFile)
	}
	return input
}

// Edits flattens the grouped input back to one edit per entry: files
// in order, then each file's edits in order. The result is empty, not
// nil, when there are no edits.
func (in EditFilesHookInput) Edits() []EditFilesEdit {
	edits := make([]EditFilesEdit, 0)
	for _, file := range in.Files {
		for _, edit := range file.Edits {
			edits = append(edits, EditFilesEdit{
				Path:       file.Path,
				OldText:    edit.OldText,
				NewText:    edit.NewText,
				ReplaceAll: edit.ReplaceAll,
			})
		}
	}
	return edits
}

func EditFiles(options EditFilesOptions) fantasy.AgentTool {
	return fantasy.NewAgentTool(
		"edit_files",
		"Perform edits on one or more files by replacing old_text with"+
			" new_text. Each entry in files must include the absolute path"+
			" of the file to edit and at least one edit. Matching is fuzzy"+
			" (tolerates whitespace and indentation differences) and preserves"+
			" the file's existing indentation and line endings. Errors if"+
			" old_text matches zero locations, or more than one unless"+
			" replace_all is set. All edits in a batch are validated before"+
			" any file is written.",
		func(ctx context.Context, args EditFilesArgs, _ fantasy.ToolCall) (fantasy.ToolResponse, error) {
			if len(args.Files) == 0 {
				return fantasy.NewTextErrorResponse("files is required"), nil
			}
			for i := range args.Files {
				args.Files[i].Path = strings.TrimSpace(args.Files[i].Path)
				if args.Files[i].Path == "" {
					return fantasy.NewTextErrorResponse(fmt.Sprintf(
						"files[%d].path is required; provide the absolute path of the file to edit; no files in this batch were applied", i,
					)), nil
				}
				if len(args.Files[i].Edits) == 0 {
					return fantasy.NewTextErrorResponse(fmt.Sprintf(
						"files[%d].edits must contain at least one edit; no files in this batch were applied", i,
					)), nil
				}
			}
			var planPath string
			if options.IsPlanTurn {
				resolvedPlanPath, err := resolvePlanTurnPath(ctx, options.ResolvePlanPath)
				if err != nil {
					return fantasy.NewTextErrorResponse(err.Error()), nil
				}
				for _, f := range args.Files {
					if f.Path != resolvedPlanPath {
						return fantasy.NewTextErrorResponse("during plan turns, edit_files is restricted to " + resolvedPlanPath), nil
					}
				}
				planPath = resolvedPlanPath
			}
			if options.GetWorkspaceConn == nil {
				return fantasy.NewTextErrorResponse("workspace connection resolver is not configured"), nil
			}
			conn, err := options.GetWorkspaceConn(ctx)
			if err != nil {
				return fantasy.NewTextErrorResponse(err.Error()), nil
			}
			if planPath != "" {
				if err := ensurePlanPathResolvesToItself(ctx, conn, planPath); err != nil {
					return fantasy.NewTextErrorResponse(err.Error()), nil
				}
			}
			return executeEditFilesTool(ctx, conn, args, options.ResolvePlanPath)
		},
	)
}

func executeEditFilesTool(
	ctx context.Context,
	conn workspacesdk.AgentConn,
	args EditFilesArgs,
	resolvePlanPath func(context.Context) (chatPath string, home string, err error),
) (fantasy.ToolResponse, error) {
	var (
		chatPath       string
		home           string
		planPathErr    error
		planPathLoaded bool
	)
	for _, file := range args.Files {
		hasPlanFileName := looksLikePlanFileName(file.Path)
		if hasPlanFileName && !isAbsolutePath(file.Path) {
			return fantasy.NewTextErrorResponse(
				"plan files must use absolute paths; use the chat-specific absolute plan path; no files in this batch were applied",
			), nil
		}
		if resolvePlanPath == nil || !hasPlanFileName {
			continue
		}
		if !planPathLoaded {
			chatPath, home, planPathErr = resolvePlanPath(ctx)
			planPathLoaded = true
		}
		if resp, rejected := rejectSharedPlanPath(file.Path, home, chatPath, planPathErr); rejected {
			return fantasy.NewTextErrorResponse(
				resp.Content + "; no files in this batch were applied",
			), nil
		}
	}

	resp, err := conn.EditFiles(ctx, workspacesdk.FileEditRequest{
		Files:       args.Files,
		IncludeDiff: true,
	})
	if err != nil {
		return fantasy.NewTextErrorResponse(agentAPIErrorMessage(err)), nil
	}
	return toolResponse(map[string]any{
		"ok":    true,
		"files": resp.Files,
	}), nil
}

// agentAPIErrorMessage preserves the agent's actionable message while
// dropping the transport metadata (HTTP method, URL, status code) that
// codersdk.Error.Error() prefixes.
func agentAPIErrorMessage(err error) string {
	sdkErr, ok := codersdk.AsError(err)
	if !ok || sdkErr.Message == "" {
		return err.Error()
	}
	var sb strings.Builder
	_, _ = sb.WriteString(sdkErr.Message)
	if sdkErr.Helper != "" {
		_, _ = sb.WriteString(": " + sdkErr.Helper)
	}
	if sdkErr.Detail != "" {
		_, _ = sb.WriteString(": " + sdkErr.Detail)
	}
	for _, v := range sdkErr.Validations {
		_, _ = sb.WriteString("\n- " + v.Field + ": " + v.Detail)
	}
	return sb.String()
}
